# -*- coding: utf-8 -*-
"""LLM Research Planner powered by GPT-OSS-120B via Groq API."""
import json
import logging
import os
import re
from typing import Any, Dict, List, Optional, Tuple
import httpx
from pydantic import BaseModel, Field

from icarus.core.worker_registry import WorkerRegistry
from icarus.schemas.base import CapabilityStatus, DomainEnum, SpatialBounds, TemporalRange
from icarus.schemas.request import MultiDomainRequest, ResearchRequest

logger = logging.getLogger("icarus.llm_planner")


class PlannedSubtask(BaseModel):
    """Subtask specification generated by LLM planner."""
    domain: DomainEnum
    task: str
    subtask_question: str
    required_models: List[str] = Field(default_factory=list)
    parameters: Dict[str, Any] = Field(default_factory=dict)
    spatial_bounds: Optional[SpatialBounds] = None
    temporal_range: Optional[TemporalRange] = None
    scientific_justification: str = ""


class StructuredResearchPlan(BaseModel):
    """Structured research plan generated by the LLM orchestrator."""
    identified_domains: List[DomainEnum]
    execution_strategy: str = Field("parallel", description="'parallel' or 'sequential'")
    subtasks: List[PlannedSubtask] = Field(..., min_length=1)
    scientific_rationale: str
    hypotheses: List[str] = Field(default_factory=list)
    potential_limitations: List[str] = Field(default_factory=list)


class LLMPlanner:
    """Orchestrates research decomposition using GPT-OSS-120B through Groq API."""

    GROQ_API_URL = "https://api.groq.com/openai/v1/chat/completions"
    DEFAULT_MODEL = "openai/gpt-oss-120b"

    def __init__(
        self,
        api_key: Optional[str] = None,
        model_name: Optional[str] = None,
        capability_registry: Optional[Any] = None,
        worker_registry: Optional[WorkerRegistry] = None,
    ):
        self.api_key = api_key or self._detect_groq_api_key()
        self.model_name = model_name or os.environ.get("GROQ_MODEL", self.DEFAULT_MODEL)
        self.cap_registry = capability_registry
        self.worker_registry = worker_registry

    def _detect_groq_api_key(self) -> Optional[str]:
        # 1. Check environment variable
        key = os.environ.get("GROQ_API_KEY")
        if key:
            return key

        # 2. Check Kaggle Secrets
        try:
            from kaggle_secrets import UserSecretsClient
            user_secrets = UserSecretsClient()
            return user_secrets.get_secret("GROQ_API_KEY")
        except Exception:
            pass

        return None

    def plan_research(
        self,
        question: str,
        user_parameters: Optional[Dict[str, Any]] = None,
    ) -> Tuple[MultiDomainRequest, StructuredResearchPlan, List[str]]:
        """Generates a structured research plan, validating it against capability and worker registries."""
        user_parameters = user_parameters or {}
        warnings: List[str] = []

        if not self.api_key:
            logger.info("GROQ_API_KEY not found; using deterministic baseline planner.")
            warnings.append("LLM planner offline (no GROQ_API_KEY); executed deterministic rule-based planner.")
            return self._deterministic_fallback_plan(question, user_parameters, warnings)

        try:
            plan = self._call_groq_planner(question, user_parameters)
        except Exception as e:
            logger.warning("Groq planning failed: %s. Falling back to deterministic planner.", str(e))
            warnings.append(f"Groq API planning failed ({str(e)}); fallen back to deterministic planner.")
            return self._deterministic_fallback_plan(question, user_parameters, warnings)

        # Validate plan against capabilities and registered workers
        validated_plan, validation_warnings = self._validate_and_sanitize_plan(plan)
        warnings.extend(validation_warnings)

        # Convert to MultiDomainRequest
        subtasks = []
        for p_task in validated_plan.subtasks:
            params = dict(user_parameters)
            params.update(p_task.parameters)
            subtask_req = ResearchRequest(
                domain=p_task.domain,
                task=p_task.task,
                research_question=p_task.subtask_question,
                required_models=p_task.required_models,
                parameters=params,
                spatial_bounds=p_task.spatial_bounds,
                temporal_range=p_task.temporal_range,
            )
            subtasks.append(subtask_req)

        multi_request = MultiDomainRequest(
            original_question=question,
            subtasks=subtasks,
            execution_mode=validated_plan.execution_strategy,
            parameters=user_parameters,
        )

        return multi_request, validated_plan, warnings

    def _call_groq_planner(self, question: str, user_parameters: Dict[str, Any]) -> StructuredResearchPlan:
        """Prompts GPT-OSS-120B on Groq to output JSON structured research plan."""
        system_prompt = self._build_system_prompt()
        user_prompt = f"Scientific Research Question: {question}\nOptional Parameters: {json.dumps(user_parameters)}"

        payload = {
            "model": self.model_name,
            "messages": [
                {"role": "system", "content": system_prompt},
                {"role": "user", "content": user_prompt},
            ],
            "response_format": {"type": "json_object"},
            "temperature": 0.1,
            "max_tokens": 2048,
        }

        headers = {
            "Authorization": f"Bearer {self.api_key}",
            "Content-Type": "application/json",
        }

        with httpx.Client(timeout=30.0) as client:
            resp = client.post(self.GROQ_API_URL, json=payload, headers=headers)
            if resp.status_code != 200:
                raise RuntimeError(f"Groq API returned HTTP {resp.status_code}: {resp.text}")

            res_json = resp.json()
            content = res_json["choices"][0]["message"]["content"]
            parsed_dict = json.loads(content)
            return StructuredResearchPlan.model_validate(parsed_dict)

    def _build_system_prompt(self) -> str:
        """Constructs system prompt grounding the LLM in ICARUS capabilities and strict rules."""
        caps_summary = ""
        if self.cap_registry and hasattr(self.cap_registry, "capabilities"):
            caps_list = [
                f"- {c['id']} ({c.get('domain')}): {c.get('name')} [Status: {c.get('status')}]"
                for c in list(self.cap_registry.capabilities.values())[:30]
            ]
            caps_summary = "\nAvailable Capabilities:\n" + "\n".join(caps_list)

        return f"""You are the central scientific research orchestrator for ICARUS (Intelligent Comprehensive Analysis and Research Unified System).
Your task is to decompose natural language scientific research questions into rigorous, executable research plans.

Supported Scientific Domains:
1. earth_observation (satellite imagery, NDVI, burn scars, floods, land cover)
2. oceans (sea surface temperature, salinity, ocean currents, wave dynamics)
3. atmosphere (wind vectors, rainfall, temperature anomalies, storm tracking)
4. solid_earth (earthquake magnitudes, seismic waveforms, fault lines)
5. climate (greenhouse gases, decadal temperature trends, drought indices)
6. heliophysics (sunspots, solar flares, geomagnetic storms, Kp index)
7. planetary (lunar/mars craters, digital elevation models, terrain slope)
8. astronomy (stellar spectral classification, exoplanet transits, light curves)
{caps_summary}

STRICT OPERATIONAL RULES:
1. You must NEVER pretend to perform scientific model inference or calculate results yourself.
2. Formulate plans strictly by assigning subtasks to domain capabilities and specialist models.
3. If a question spans multiple domains (e.g. climate impact on vegetation), decompose it into separate subtasks for each domain.
4. Output MUST be a valid JSON object matching this schema:
{{
  "identified_domains": ["earth_observation", ...],
  "execution_strategy": "parallel" or "sequential",
  "scientific_rationale": "Explanation of methodology",
  "hypotheses": ["Testable scientific hypothesis"],
  "potential_limitations": ["Sensor limitations, resolution, etc."],
  "subtasks": [
    {{
      "domain": "earth_observation",
      "task": "eo_vegetation_analysis",
      "subtask_question": "Compute NDVI index",
      "required_models": ["prithvi-eo-2.0-300m"],
      "parameters": {{}},
      "scientific_justification": "Why this task is needed"
    }}
  ]
}}"""

    def _validate_and_sanitize_plan(
        self, plan: StructuredResearchPlan
    ) -> Tuple[StructuredResearchPlan, List[str]]:
        """Ensures LLM output does not hallucinate non-existent domains or capabilities."""
        warnings = []
        sanitized_subtasks = []

        valid_domains = {d.value for d in DomainEnum}

        for st in plan.subtasks:
            # Check domain validity
            dom_val = st.domain if isinstance(st.domain, str) else st.domain.value
            if dom_val not in valid_domains:
                warnings.append(f"LLM proposed invalid domain '{dom_val}', mapped to 'earth_observation'.")
                st.domain = DomainEnum.EARTH_OBSERVATION

            # Check capability in registry if available
            if self.cap_registry and hasattr(self.cap_registry, "get_capability"):
                meta = self.cap_registry.get_capability(st.task)
                if not meta:
                    # Try finding closest matching capability
                    found_cap = False
                    for cid, cdata in getattr(self.cap_registry, "capabilities", {}).items():
                        if st.domain == cdata.get("domain") and (st.task in cid or cid in st.task):
                            st.task = cid
                            found_cap = True
                            break
                    if not found_cap:
                        warnings.append(f"Capability '{st.task}' not found in registry; flagged as experimental.")

            # Check if active workers support this task
            if self.worker_registry:
                candidates = self.worker_registry.find_workers_for_task(
                    domain=st.domain, task=st.task, required_models=st.required_models
                )
                if not candidates:
                    warnings.append(
                        f"Notice: No active worker node currently registered for domain='{st.domain}' task='{st.task}'."
                    )

            sanitized_subtasks.append(st)

        plan.subtasks = sanitized_subtasks
        return plan, warnings

    def _deterministic_fallback_plan(
        self, question: str, user_parameters: Dict[str, Any], warnings: List[str]
    ) -> Tuple[MultiDomainRequest, StructuredResearchPlan, List[str]]:
        """Deterministic keyword-based planner when LLM is unavailable."""
        q_lower = question.lower()
        subtasks: List[PlannedSubtask] = []
        identified_domains: List[DomainEnum] = []

        domain_keywords = {
            DomainEnum.EARTH_OBSERVATION: ["satellite", "sentinel", "landsat", "ndvi", "vegetation", "canopy", "burn", "flood", "forest", "crop"],
            DomainEnum.OCEANS: ["ocean", "sea", "sst", "salinity", "marine", "current", "wave", "tide"],
            DomainEnum.ATMOSPHERE: ["weather", "wind", "rain", "precipitation", "storm", "cyclone", "temperature", "forecast"],
            DomainEnum.SOLID_EARTH: ["earthquake", "seismic", "fault", "magnitude", "aftershock", "tremor"],
            DomainEnum.CLIMATE: ["climate", "greenhouse", "co2", "warming", "drought", "trend", "decade"],
            DomainEnum.HELIOPHYSICS: ["sun", "solar", "sunspot", "geomagnetic", "kp", "flare", "cme"],
            DomainEnum.PLANETARY: ["crater", "lunar", "moon", "mars", "elevation", "slope", "dem"],
            DomainEnum.ASTRONOMY: ["star", "galaxy", "stellar", "spectrum", "exoplanet", "transit", "telescope"],
        }

        default_tasks = {
            DomainEnum.EARTH_OBSERVATION: "eo_vegetation_analysis",
            DomainEnum.OCEANS: "ocean_sea_surface_temperature",
            DomainEnum.ATMOSPHERE: "atmos_wind_analysis",
            DomainEnum.SOLID_EARTH: "solid_earth_earthquake_magnitude_location",
            DomainEnum.CLIMATE: "climate_trends",
            DomainEnum.HELIOPHYSICS: "helio_geomagnetic_storm_analysis",
            DomainEnum.PLANETARY: "planetary_crater_statistics",
            DomainEnum.ASTRONOMY: "astro_stellar_classification",
        }

        for dom, keywords in domain_keywords.items():
            if any(re.search(r'\b' + re.escape(kw) + r'\b', q_lower) for kw in keywords):
                identified_domains.append(dom)
                subtasks.append(
                    PlannedSubtask(
                        domain=dom,
                        task=default_tasks[dom],
                        subtask_question=f"Analyze {dom.value} aspects of: {question}",
                        scientific_justification=f"Keyword match for domain {dom.value}",
                    )
                )

        if not identified_domains:
            identified_domains.append(DomainEnum.EARTH_OBSERVATION)
            subtasks.append(
                PlannedSubtask(
                    domain=DomainEnum.EARTH_OBSERVATION,
                    task="eo_vegetation_analysis",
                    subtask_question=question,
                    scientific_justification="Default domain assignment",
                )
            )

        plan = StructuredResearchPlan(
            identified_domains=identified_domains,
            execution_strategy="parallel",
            subtasks=subtasks,
            scientific_rationale="Deterministic baseline keyword routing.",
            hypotheses=["Relevant scientific metrics can be derived from available algorithmic adapters."],
            potential_limitations=["Baseline planner cannot perform contextual semantic domain decomposition."],
        )

        request_subtasks = [
            ResearchRequest(
                domain=st.domain,
                task=st.task,
                research_question=st.subtask_question,
                parameters=user_parameters,
            )
            for st in subtasks
        ]

        multi_request = MultiDomainRequest(
            original_question=question,
            subtasks=request_subtasks,
            execution_mode="parallel",
            parameters=user_parameters,
        )

        return multi_request, plan, warnings

